// ── global setup entry point ───────────────────────────────────────────────────
export default async function globalSetup(): Promise<void> {
  console.log('\n[GlobalSetup] Bootstrapping NestJS in-process test server (all services mocked)...');

  // ── Determine which admin email to pre-seed ──────────────────────────────
  // When the module-executor runs subsequent specs (school, educator, etc.)
  // each gets a fresh in-memory server. We read the testUserEmail saved by the
  // auth spec into execution-data.json and pre-seed that user with the
  // expected password so later specs can authenticate against this fresh server.
  //
  // We always pre-seed BOTH the static default AND any dynamic email saved in
  // execution-data.json (they may differ when the auth spec ran first in the
  // module executor and saved a dynamic email).
  const emailsToPreseed = new Set<string>([PRESEEDED_ADMIN_EMAIL]);

  try {
    if (fs.existsSync(EXECUTION_DATA_FILE)) {
      const execData = JSON.parse(fs.readFileSync(EXECUTION_DATA_FILE, 'utf-8')) as { auth?: { testUserEmail?: string } };
      const saved = execData.auth?.testUserEmail;
      if (saved) {
        emailsToPreseed.add(saved);
        console.log(`[GlobalSetup] Also pre-seeding testUserEmail from execution-data: ${saved}`);
      }
    }
  } catch { /* ignore */ }

  console.log(`[GlobalSetup] Pre-seeding emails: ${[...emailsToPreseed].join(', ')}`);

  // Also ensure execution-data.json always has at least the static default so
  // specs that run in isolation (without the module executor) find a valid email.
  try {
    const dir = path.dirname(EXECUTION_DATA_FILE);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    const base = fs.existsSync(EXECUTION_DATA_FILE)
      ? JSON.parse(fs.readFileSync(EXECUTION_DATA_FILE, 'utf-8'))
      : {};
    if (!base.auth?.testUserEmail) {
      base.auth = { ...(base.auth ?? {}), testUserEmail: PRESEEDED_ADMIN_EMAIL };
      fs.writeFileSync(EXECUTION_DATA_FILE, JSON.stringify(base, null, 2), 'utf-8');
    }
  } catch { /* ignore */ }

  // Pre-populate _users with all relevant admin accounts.
  const preseedHash = await bcrypt.hash(PRESEEDED_ADMIN_PASSWORD, 10);
  for (const email of emailsToPreseed) {
    _users.set(email, { id: uuid(), email, passwordHash: preseedHash, fullName: 'Pre-Seeded Admin', role: 'District Admin' });
  }

  // Pre-seed educator from registerApi.json so class/student/simulation specs
  // can log in as educator even when running after a fresh globalSetup.
  const REGISTER_API_FILE = path.resolve(__dirname, 'test-data/registerApi.json');
  try {
    if (fs.existsSync(REGISTER_API_FILE)) {
      const regData = JSON.parse(fs.readFileSync(REGISTER_API_FILE, 'utf-8')) as {
        educatorcreate?: { email?: string; password?: string; firstName?: string };
        adminUser?: { email?: string; password?: string; full_name?: string };
        adminUser2?: { email?: string; password?: string; full_name?: string };
        loginUser?: { email?: string; password?: string };
      };
      const edEmail = regData.educatorcreate?.email;
      const edPassword = regData.educatorcreate?.password ?? 'Test@123';
      if (edEmail && !_users.has(edEmail)) {
        const edHash = await bcrypt.hash(edPassword, 10);
        const edId = uuid();
        _users.set(edEmail, { id: edId, email: edEmail, passwordHash: edHash, fullName: regData.educatorcreate?.firstName ?? 'Educator', role: 'Educator' });
        // Also seed a matching educator record so findEducatorById works in ClassesController
        _educators.set(edId, { id: edId, email: edEmail, fullName: regData.educatorcreate?.firstName ?? 'Educator', adminId: [..._users.values()].find(u => u.role === 'District Admin')?.id ?? '', schoolId: '', status: 'ACTIVE', is_active: true });
        console.log(`[GlobalSetup] Pre-seeded educator from registerApi.json: ${edEmail}`);
      }
      // Pre-seed admin users so delete spec can login with loginUser/adminUser credentials
      for (const adminKey of ['adminUser', 'adminUser2', 'loginUser'] as const) {
        const adminEntry = regData[adminKey];
        const aEmail = adminEntry?.email;
        const aPassword = adminEntry?.password ?? 'Test@123';
        if (aEmail && !_users.has(aEmail)) {
          const aHash = await bcrypt.hash(aPassword, 10);
          _users.set(aEmail, { id: uuid(), email: aEmail, passwordHash: aHash, fullName: (adminEntry as any)?.full_name ?? 'Admin', role: 'District Admin' });
        }
      }
    }
  } catch { /* ignore */ }

  const port = await getFreePort();

  const mockCsrfService = {
    generateToken: () => 'mock-csrf-token-pre-deploy',
    storeToken: () => Promise.resolve(),
    validateToken: () => Promise.resolve(true),
    revokeToken: () => Promise.resolve(),
  };

  const mockClsService = {
    set: () => {},
    get: () => undefined,
    run: (cb: () => unknown) => cb(),
  };

  const moduleRef: TestingModule = await Test.createTestingModule({
    imports: [
      PassportModule.register({ defaultStrategy: 'jwt' }),
      JwtModule.register({
        secret: TEST_JWT_SECRET,
        signOptions: { expiresIn: '1d' },
      }),
    ],

    controllers: [
      AppController,
      AuthController,
      SchoolsController,
      EducatorsController,
      DashboardController,
      ClassesController,
      StudentsController,
      SimulationCatalogController,
      EducatorSimulationsController,
      InvitesController,
      UsersController,
      SimulationsController,
    ],

    providers: [
      AppService,
      TokenBlacklistService,
      JwtStrategy,
      JwtAuthGuard,
      Reflector,

      {
        provide: ConfigService,
        useValue: {
          get: (key: string) => {
            if (key === 'JWT_SECRET') return TEST_JWT_SECRET;
            if (key === 'JWT_EXPIRES_IN') return '1d';
            if (key === 'FRONTEND_URL') return 'http://localhost:3001';
            return process.env[key] ?? null;
          },
          getOrThrow: (key: string) => {
            if (key === 'JWT_SECRET') return TEST_JWT_SECRET;
            throw new Error(`[MockConfig] ${key} not configured`);
          },
        },
      },

      { provide: EducatorSessionService, useValue: { isTokenInvalidated: () => Promise.resolve(false), invalidateBySchool: () => Promise.resolve([]) } },
      { provide: ClsService, useValue: mockClsService },
      { provide: CsrfService, useValue: mockCsrfService },
      { provide: AzureBlobService, useValue: { uploadFile: () => Promise.resolve(''), deleteFile: () => Promise.resolve(), generateSasUrl: (u: string) => Promise.resolve(u), isConfigured: () => false } },

      { provide: AuthService, useValue: buildMockAuthService() },
      { provide: SchoolsService, useValue: buildMockSchoolsService() },
      { provide: EducatorsService, useValue: buildMockEducatorsService() },
      { provide: DashboardService, useValue: buildMockDashboardService() },
      { provide: ClassesService, useValue: buildMockClassesService() },
      { provide: StudentsService, useValue: buildMockStudentsService() },
      { provide: SimulationCatalogService, useValue: buildMockSimulationCatalogService() },
      { provide: EducatorSimulationsService, useValue: buildMockEducatorSimulationsService() },
      { provide: InvitesService, useValue: buildMockInvitesService() },
      { provide: UsersService, useValue: buildMockUsersService() },
      { provide: SimulationsService, useValue: buildMockSimulationsService() },
      { provide: LmsConfigService, useValue: {
        upsertConfig: async () => null,
        findSchoolbyIssuer: async () => null,
        findByIssuer: async () => null,
        findByClientId: async () => null,
        findSchoolByClientId: async () => null,
        getBySchoolId: async () => null,
        getOptionalBySchoolId: async () => null,
      }},
      { provide: LmsRosterService, useValue: {
        fetchRoster: async () => ({ members: [] }),
        fetchRosterWithWsFallback: async () => ({ members: [] }),
      }},
      { provide: LmsLookupService, useValue: {
        lookupStudentProfile: async () => null,
        findStudentCodeByLmsUserId: async () => null,
        findStudentByConstructedCode: async () => null,
        findStudentCodeByLmsClassAndUserId: async () => null,
        findStudentCodeByLmsUserIdInSchool: async () => null,
        findStudentCodeByLmsUserIdGlobally: async () => null,
        ensureMappedStudentAccount: async () => null,
      }},

      { provide: APP_GUARD, useClass: NoOpCsrfGuard },
    ],
  }).compile();

  const app: INestApplication = moduleRef.createNestApplication();

  app.use(cookieParser());
  app.setGlobalPrefix('api');
  app.useGlobalPipes(
    new ValidationPipe({ whitelist: true, forbidNonWhitelisted: true, transform: true }),
  );
  app.useGlobalFilters(new HttpExceptionFilter());

  await app.listen(port, '127.0.0.1');

  const jwtService = moduleRef.get(JwtService);
  const testToken = jwtService.sign({
    sub: 'pre-deploy-admin-id',
    email: 'admin@predeployment.test',
    roles: ['District Admin'],
    type: 'admin',
    userId: 'pre-deploy-admin-id',
  });

  fs.writeFileSync(
    PORT_FILE,
    JSON.stringify({ port, baseURL: `http://127.0.0.1:${port}/api`, testToken }),
    'utf-8',
  );

  global.__PRE_DEPLOY_APP__ = app;

  console.log(`[GlobalSetup] Test server running at http://127.0.0.1:${port}/api`);
  console.log(`[GlobalSetup] Port file: ${PORT_FILE}`);
}

import fs from 'fs';
import path from 'path';
import type { Reporter, TestResult, Test, AggregatedResult } from '@jest/reporters';
import { renderHtmlReport } from './report-template';
import type { ReportData, ScenarioType, TestSummaryRow } from './report-types';

const normalizeText = (value: string): string => value.trim().toLowerCase();

const formatCapitalized = (value: string): string =>
  value.replace(/(^|\s)([a-z])/g, (_, prefix: string, letter: string): string => `${prefix}${letter.toUpperCase()}`);

const inferScenarioType = (title: string): ScenarioType => {
  const negativePatterns = [
    'invalid',
    'missing',
    'unauthorized',
    'expired',
    'duplicate',
    'not found',
    'notfound',
    'error',
    'malformed',
    'empty',
    'forbidden',
    'unauthenticated',
    'bad request',
    'failed',
    'invalid token',
    'invalid email',
    'invalid password',
    'invalid uuid',
    'invalid id',
    'invalid query',
    'invalid path',
    'invalid enum',
    'invalid status',
  ];

  if (negativePatterns.some((pattern) => normalizeText(title).includes(pattern))) {
    return 'NEGATIVE';
  }

  return 'POSITIVE';
};

const createModuleName = (filePath: string): string => {
  const normalized = filePath.replace(/\\/g, '/');
  const parts = normalized.split('/');
  const modulesIndex = parts.indexOf('modules');
  if (modulesIndex !== -1 && parts.length > modulesIndex + 1) {
    const moduleName = parts[modulesIndex + 1];
    return `${formatCapitalized(moduleName)} Module`;
  }
  return 'General Module';
};

const buildFileName = (filePath: string): string => path.basename(filePath);

const createReportRow = (title: string, filePath: string, status: 'Passed' | 'Failed' | 'Skipped', duration: number, errorMessage?: string): TestSummaryRow => {
  const scenarioType = inferScenarioType(title);
  const whyPassed = 'All validation checks passed, including status and response payload assertions.';
  const whyFailed = errorMessage || 'Assertion failed or response validation did not match expected values.';

  return {
    title,
    description: title,
    status,
    scenarioType,
    fileName: buildFileName(filePath),
    moduleName: createModuleName(filePath),
    location: buildFileName(filePath),
    durationMs: duration,
    expectedResult: 'The API should return the expected HTTP status and response body with the expected contract.',
    actualResult: status === 'Failed' ? whyFailed : 'The API responded as expected and all assertions passed successfully.',
    whyPassed,
    whyFailed,
  };
};

const groupByModule = (rows: TestSummaryRow[]): Map<string, TestSummaryRow[]> => {
  const moduleMap = new Map<string, Array<TestSummaryRow>>();
  for (const row of rows) {
    const moduleRows = moduleMap.get(row.moduleName) ?? [];
    moduleRows.push(row);
    moduleMap.set(row.moduleName, moduleRows);
  }
  return moduleMap;
};

const groupFiles = (rows: TestSummaryRow[]): Map<string, TestSummaryRow[]> => {
  const fileMap = new Map<string, Array<TestSummaryRow>>();
  for (const row of rows) {
    const fileRows = fileMap.get(row.fileName) ?? [];
    fileRows.push(row);
    fileMap.set(row.fileName, fileRows);
  }
  return fileMap;
};

const computeModuleSummary = (
  name: string,
  rows: TestSummaryRow[]
): {
  name: string;
  tests: TestSummaryRow[];
  files: Array<{ name: string; count: number; tests: TestSummaryRow[] }>;
  passed: number;
  failed: number;
  skipped: number;
  positive: number;
  negative: number;
} => {
  const fileMap = groupFiles(rows);
  const files = Array.from(fileMap.entries()).map(([name, tests]) => ({
    name,
    count: tests.length,
    tests,
  }));

  const passed = rows.filter((row) => row.status === 'Passed').length;
  const failed = rows.filter((row) => row.status === 'Failed').length;
  const skipped = rows.filter((row) => row.status === 'Skipped').length;
  const positive = rows.filter((row) => row.scenarioType === 'POSITIVE').length;
  const negative = rows.filter((row) => row.scenarioType === 'NEGATIVE').length;

  return {
    name,
    tests: rows,
    files,
    passed,
    failed,
    skipped,
    positive,
    negative,
  };
};

const buildReportData = (rows: TestSummaryRow[]): ReportData => {
  const moduleMap = groupByModule(rows);
  const modules = Array.from(moduleMap.entries()).map(([module, moduleRows]) => computeModuleSummary(module, moduleRows));

  const passed = rows.filter((row) => row.status === 'Passed').length;
  const failed = rows.filter((row) => row.status === 'Failed').length;
  const skipped = rows.filter((row) => row.status === 'Skipped').length;
  const positive = rows.filter((row) => row.scenarioType === 'POSITIVE').length;
  const negative = rows.filter((row) => row.scenarioType === 'NEGATIVE').length;
  const durationMs = rows.reduce((s, r) => s + (r.durationMs || 0), 0);
  const durationDisplay = ((): string => {
    const totalSeconds = Math.round((durationMs || 0) / 1000);
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return minutes > 0 ? `${minutes}m ${seconds}s` : `${seconds}s`;
  })();

  return {
    title: 'Educator API Test Report',
    generatedAt: new Date().toISOString(),
    totalTests: rows.length,
    passed,
    failed,
    skipped,
    positive,
    negative,
    durationMs,
    durationDisplay,
    modules,
  };
};

const ensureReportsDirectory = (reportPath: string): void => {
  const directory = path.dirname(reportPath);
  if (!fs.existsSync(directory)) {
    fs.mkdirSync(directory, { recursive: true });
  }
};

class EducatorApiJestReporter implements Reporter {
  private rows: TestSummaryRow[] = [];
  private startTime: number = Date.now();

  onRunStart(): void {
    this.rows = [];
    this.startTime = Date.now();
  }

  onTestResult(_test: Test, testResult: TestResult, _aggregatedResult: AggregatedResult): void {
    const filePath = testResult.testFilePath;
    
    for (const test of testResult.testResults) {
      const status = test.status === 'passed' ? 'Passed' : test.status === 'skipped' ? 'Skipped' : 'Failed';
      const errorMessage = test.failureMessages ? test.failureMessages.join(' | ') : undefined;
      const duration = test.duration || 0;

      const row = createReportRow(test.title, filePath, status, duration, errorMessage);
      this.rows.push(row);
    }
  }

  onRunComplete(): void {
    const reportData = buildReportData(this.rows);
    const htmlContent = renderHtmlReport(reportData);
    const reportPath = path.resolve(__dirname, '../reports/html/api-test-report.html');
    
    ensureReportsDirectory(reportPath);
    fs.writeFileSync(reportPath, htmlContent, 'utf-8');
      }
}

export default EducatorApiJestReporter;

import fs from 'fs';
import path from 'path';

/**
 * ============================================================================
 * EXECUTION DATA MANAGER
 * ============================================================================
 * 
 * Manages centralized storage and retrieval of entity IDs across test modules.
 * Captures all created resource IDs during test execution for cleanup phase.
 * 
 * Usage:
 *   1. Initialize: ExecutionDataManager.initialize()
 *   2. Save IDs: ExecutionDataManager.saveEntityId('school', schoolId)
 *   3. Retrieve: ExecutionDataManager.getEntityIds('school')
 *   4. Finalize: ExecutionDataManager.finalize()
 * 
 * Data stored in: tests/api/test-data/execution-data.json
 * ============================================================================
 */

interface EntityData {
  created: string[];
  deleted: string[];
  deletedCount: number;
  failedCount: number;
}

interface CleanupResult {
  entity: string;
  id: string;
  status: 'deleted' | 'failed' | 'pending';
  httpStatus?: number;
  message?: string;
}

interface CleanupData {
  status: 'pending' | 'in-progress' | 'completed' | 'failed';
  startTime?: string;
  endTime?: string;
  results: CleanupResult[];
}

interface ExecutionData {
  executionId: string;
  startTime: string;
  endTime?: string;
  status: 'in-progress' | 'completed' | 'interrupted';
  auth: {
    userId?: string;
    accessToken?: string;
    testUserEmail?: string;
  };
  entities: {
    school: EntityData;
    educator: EntityData;
    class: EntityData;
    student: EntityData;
    simulation?: EntityData;
  };
  cleanup: CleanupData;
}

/**
 * Execution Data Manager Class
 * Handles centralized ID storage for all test modules
 */
export class ExecutionDataManager {
  private static readonly DATA_DIR = path.resolve(
    __dirname,
    '../test-data'
  );

  private static readonly DATA_FILE = path.join(
    ExecutionDataManager.DATA_DIR,
    'execution-data.json'
  );

  /**
   * Initialize execution data
   * Called at the start of test run
   */
  static initialize(): void {
    try {
      // Ensure directory exists
      if (!fs.existsSync(ExecutionDataManager.DATA_DIR)) {
        fs.mkdirSync(ExecutionDataManager.DATA_DIR, {
          recursive: true,
        });
      }

      const executionData: ExecutionData = {
        executionId: new Date().toISOString(),
        startTime: new Date().toISOString(),
        status: 'in-progress',
        auth: {},
        entities: {
          school: {
            created: [],
            deleted: [],
            deletedCount: 0,
            failedCount: 0,
          },
          educator: {
            created: [],
            deleted: [],
            deletedCount: 0,
            failedCount: 0,
          },
          class: {
            created: [],
            deleted: [],
            deletedCount: 0,
            failedCount: 0,
          },
          student: {
            created: [],
            deleted: [],
            deletedCount: 0,
            failedCount: 0,
          },
          simulation: {
            created: [],
            deleted: [],
            deletedCount: 0,
            failedCount: 0,
          },
        },
        cleanup: {
          status: 'pending',
          results: [],
        },
      };

      fs.writeFileSync(
        ExecutionDataManager.DATA_FILE,
        JSON.stringify(executionData, null, 2)
      );
    } catch (error) {
      throw error;
    }
  }

  static saveEntityId(entity: string, id: string): void {
    try {
      const data = ExecutionDataManager.getExecutionData();

      if (!data.entities[entity as keyof typeof data.entities]) {
        (data.entities[entity as keyof typeof data.entities] as EntityData) = {
          created: [],
          deleted: [],
          deletedCount: 0,
          failedCount: 0,
        };
      }

      if (id && !(data.entities[entity as keyof typeof data.entities] as EntityData).created.includes(id)) {
        (data.entities[entity as keyof typeof data.entities] as EntityData).created.push(id);
      }

      fs.writeFileSync(
        ExecutionDataManager.DATA_FILE,
        JSON.stringify(data, null, 2)
      );
    } catch (error) {
      console.error(
        `Failed to save entity ID for ${entity}:`,
        error instanceof Error ? error.message : String(error)
      );
    }
  }

  static getEntityIds(entity: string): string[] {
    try {
      const data = ExecutionDataManager.getExecutionData();
      const entityData = data.entities[entity as keyof typeof data.entities];
      return entityData?.created || [];
    } catch (error) {
      console.error(
        `Failed to get entity IDs for ${entity}:`,
        error instanceof Error ? error.message : String(error)
      );
      return [];
    }
  }

  /**
   * Set authentication data
   * @param userId - User ID from login response
   * @param accessToken - Access token for API calls
   */
  static setAuthData(userId: string, accessToken: string): void {
    try {
      const data = ExecutionDataManager.getExecutionData();
      data.auth = { userId, accessToken };
      fs.writeFileSync(
        ExecutionDataManager.DATA_FILE,
        JSON.stringify(data, null, 2)
      );
    } catch (error) {
      console.error(
        'Failed to set auth data:',
        error instanceof Error ? error.message : String(error)
      );
    }
  }

  /**
   * Get authentication data
   * @returns Auth data (userId and accessToken)
   */
  static getAuthData(): { userId?: string; accessToken?: string } {
    try {
      const data = ExecutionDataManager.getExecutionData();
      return data.auth || {};
    } catch {
      return {};
    }
  }

  /**
   * Update cleanup status
   * @param entity - Entity type
   * @param id - Entity ID
   * @param status - Deletion status
   * @param httpStatus - HTTP status code
   * @param message - Response message
   */
  static updateCleanupStatus(
    entity: string,
    id: string,
    status: 'deleted' | 'failed' | 'pending',
    httpStatus?: number,
    message?: string
  ): void {
    try {
      const data = ExecutionDataManager.getExecutionData();

      const result: CleanupResult = {
        entity,
        id,
        status,
        httpStatus,
        message,
      };

      data.cleanup.results.push(result);

      const entityData = data.entities[entity as keyof typeof data.entities];
      if (entityData) {
        if (status === 'deleted') {
          entityData.deletedCount++;
          if (!entityData.deleted.includes(id)) {
            entityData.deleted.push(id);
          }
        } else if (status === 'failed') {
          entityData.failedCount++;
        }
      }

      fs.writeFileSync(
        ExecutionDataManager.DATA_FILE,
        JSON.stringify(data, null, 2)
      );
    } catch (error) {
      console.error(
        `Failed to update cleanup status for ${entity}:`,
        error instanceof Error ? error.message : String(error)
      );
    }
  }

  /**
   * Get complete execution data
   * @returns Full execution data object
   */
  static getExecutionData(): ExecutionData {
    try {
      if (!fs.existsSync(ExecutionDataManager.DATA_FILE)) {
        throw new Error('Execution data file not found');
      }

      const content = fs.readFileSync(
        ExecutionDataManager.DATA_FILE,
        'utf-8'
      );
      return JSON.parse(content) as ExecutionData;
    } catch (error) {
      console.error(
        'Failed to read execution data:',
        error instanceof Error ? error.message : String(error)
      );
      throw error;
    }
  }

  /**
   * Finalize execution data
   * Called at end of test run
   */
  static finalize(): void {
    try {
      const data = ExecutionDataManager.getExecutionData();
      data.endTime = new Date().toISOString();
      data.status = 'completed';

      if (data.cleanup.results.length > 0) {
        data.cleanup.status = 'completed';
        data.cleanup.endTime = new Date().toISOString();
      }

      fs.writeFileSync(
        ExecutionDataManager.DATA_FILE,
        JSON.stringify(data, null, 2)
      );
    } catch (error) {
      console.error(
        'Failed to finalize execution data:',
        error instanceof Error ? error.message : String(error)
      );
    }
  }

  static markInterrupted(): void {
    try {
      const data = ExecutionDataManager.getExecutionData();
      data.status = 'interrupted';
      data.endTime = new Date().toISOString();

      fs.writeFileSync(
        ExecutionDataManager.DATA_FILE,
        JSON.stringify(data, null, 2)
      );
    } catch (error) {
      console.error(
        'Failed to mark execution as interrupted:',
        error instanceof Error ? error.message : String(error)
      );
    }
  }

  static reset(): void {
    try {
      if (fs.existsSync(ExecutionDataManager.DATA_FILE)) {
        fs.unlinkSync(ExecutionDataManager.DATA_FILE);
      }
    } catch (error) {
      console.error(
        'Failed to reset execution data:',
        error instanceof Error ? error.message : String(error)
      );
    }
  }

  static getCleanupSummary(): {
    total: number;
    deleted: number;
    failed: number;
  } {
    try {
      const data = ExecutionDataManager.getExecutionData();
      const results = data.cleanup.results;

      return {
        total: results.length,
        deleted: results.filter((r) => r.status === 'deleted').length,
        failed: results.filter((r) => r.status === 'failed').length,
      };
    } catch {
      return { total: 0, deleted: 0, failed: 0 };
    }
  }

  /**
   * Set test user email
   * @param email - Dynamically generated test user email
   */
  static setTestUserEmail(email: string): void {
    try {
      const data = ExecutionDataManager.getExecutionData();
      data.auth.testUserEmail = email;
      fs.writeFileSync(
        ExecutionDataManager.DATA_FILE,
        JSON.stringify(data, null, 2)
      );
    } catch (error) {
      console.error(
        'Failed to set test user email:',
        error instanceof Error ? error.message : String(error)
      );
    }
  }

  /**
   * Get test user email
   * @returns Test user email or undefined if not set
   */
  static getTestUserEmail(): string | undefined {
    try {
      const data = ExecutionDataManager.getExecutionData();
      return data.auth?.testUserEmail;
    } catch {
      return undefined;
    }
  }
}

export default ExecutionDataManager;
